import json,glob
# find steps whose predicted body positionally asserts arrays of length>=2 (order-sensitive)
def arrays(obj, path=""):
    out=[]
    if isinstance(obj, dict):
        for k,v in obj.items():
            out+=arrays(v, path+"."+k)
    elif isinstance(obj, list):
        out.append((path, len(obj)))
        for i,v in enumerate(obj):
            out+=arrays(v, path+f".{i}")
    return out
for f in sorted(glob.glob('*/*.json')):
    d=json.load(open(f,encoding='utf-8'))
    for name,pred in (d.get('predicted') or {}).items():
        hits=[]
        for body in (pred.get('body') or {}).items() if False else []:
            pass
        b=pred.get('body')
        if isinstance(b,dict):
            for path,l in arrays(b):
                if l>=2: hits.append((path,l))
        if hits:
            print(f, d.get('id'), name, hits)
